  'ppage.faqsTitle': { en: 'Frequently Asked Questions', te: 'తరచుగా అడిగే ప్రశ్నలు', hi: 'अक्सर पूछे जाने वाले प्रश्न' },
  'ppage.faq1q': { en: 'How do I book an appointment?', te: 'నేను అపాయింట్‌మెంట్ ఎలా బుక్ చేయాలి?', hi: 'मैं अपॉइंटमेंट कैसे बुक करूं?' },
  'ppage.faq1a': { en: 'Go to Doctors or Book Appointment, pick a doctor and a slot, then confirm to get a digital token.', te: 'డాక్టర్లు లేదా అపాయింట్‌మెంట్ బుకింగ్‌కు వెళ్లి, డాక్టర్ మరియు స్లాట్‌ను ఎంచుకుని, ధృవీకరిస్తే డిజిటల్ టోకెన్ లభిస్తుంది.', hi: 'डॉक्टर या अपॉइंटमेंट बुक करें पर जाएँ, डॉक्टर और स्लॉट चुनें, फिर पुष्टि करके डिजिटल टोकन पाएँ।' },
  // Previous fee question: 'ppage.faq2q': { en: 'What is the platform fee?', te: 'ప్లాట్‌ఫామ్ ఫీజు అంటే ఏమిటి?', hi: 'प्लेटफॉर्म शुल्क क्या है?' },
  'ppage.faq2q': { en: 'Is there a booking fee?', te: 'బుకింగ్ ఫీజు ఉందా?', hi: 'क्या बुकिंग शुल्क है?' },
  'ppage.faq2a': { en: 'There is no platform fee for booking. The doctor’s consultation fee is paid separately at the hospital.', te: 'బుకింగ్‌కు ప్లాట్‌ఫారమ్ ఫీజు లేదు. డాక్టర్ కన్సల్టేషన్ ఫీజును ఆసుపత్రిలో విడిగా చెల్లించాలి.', hi: 'बुकिंग के लिए कोई प्लेटफ़ॉर्म शुल्क नहीं है। डॉक्टर की परामर्श फ़ीस अस्पताल में अलग से दी जाती है।' },
  'ppage.faq3q': { en: 'How does the live queue work?', te: 'లైవ్ క్యూ ఎలా పని చేస్తుంది?', hi: 'लाइव कतार कैसे काम करती है?' },
  'ppage.faq3a': { en: 'Your token shows your position in real time. You’ll get alerts as the queue moves so you can reach on time.', te: 'మీ టోకెన్ మీ స్థానాన్ని రియల్ టైమ్‌లో చూపిస్తుంది. క్యూ కదులుతున్నప్పుడు మీరు హెచ్చరికలు పొందుతారు, తద్వారా మీరు సమయానికి చేరుకోగలరు.', hi: 'आपका टोकन रियल टाइम में आपकी स्थिति दिखाता है। कतार बढ़ने पर आपको अलर्ट मिलेंगे ताकि आप समय पर पहुंच सकें।' },
  'ppage.faq4q': { en: 'Can I cancel or reschedule?', te: 'నేను రద్దు చేయవచ్చా లేదా రీషెడ్యూల్ చేయవచ్చా?', hi: 'क्या मैं रद्द या पुनर्निर्धारित कर सकता हूं?' },
  'ppage.faq4a': { en: 'Yes — open My Appointments, choose the appointment, and select reschedule or cancel before your slot.', te: 'అవును — నా అపాయింట్‌మెంట్లను తెరిచి, అపాయింట్‌మెంట్‌ను ఎంచుకుని, మీ స్లాట్‌కు ముందు రీషెడ్యూల్ లేదా రద్దును ఎంచుకోండి.', hi: 'हाँ — मेरी अपॉइंटमेंट खोलें, अपॉइंटमेंट चुनें, और अपने स्लॉट से पहले पुनर्निर्धारित या रद्द करें चुनें।' },
  'ppage.faq5q': { en: 'Are my health records private?', te: 'నా ఆరోగ్య రికార్డులు గోప్యమేనా?', hi: 'क्या मेरे स्वास्थ्य रिकॉर्ड निजी हैं?' },
  'ppage.faq5a': { en: 'Yes. Records are encrypted and only you can access them. We never share data without your consent.', te: 'అవును. రికార్డులు ఎన్‌క్రిప్ట్ చేయబడ్డాయి మరియు మీరు మాత్రమే వాటిని యాక్సెస్ చేయగలరు. మీ సమ్మతి లేకుండా మేము ఎప్పటికీ డేటాను పంచుకోము.', hi: 'हाँ। रिकॉर्ड एन्क्रिप्टेड हैं और केवल आप उन्हें एक्सेस कर सकते हैं। हम आपकी सहमति के बिना कभी डेटा साझा नहीं करते।' },

  // ---------- Coming Soon ----------
  'ppage.comingSoon': { en: 'This screen is coming soon', te: 'ఈ స్క్రీన్ త్వరలో వస్తోంది', hi: 'यह स्क्रीन जल्द आ रही है' },
  'ppage.comingSoonDesc': { en: "We're designing this part of your dashboard next. Meanwhile, head back to your dashboard.", te: 'మేము మీ డ్యాష్‌బోర్డ్‌లోని ఈ భాగాన్ని తర్వాత డిజైన్ చేస్తున్నాం. ఈలోగా, మీ డ్యాష్‌బోర్డ్‌కు తిరిగి వెళ్లండి.', hi: 'हम आपके डैशबोर्ड के इस हिस्से को अगला डिज़ाइन कर रहे हैं। इस बीच, अपने डैशबोर्ड पर वापस जाएं।' },
  'ppage.backToDashboardArrow': { en: '← Back to Dashboard', te: '← డ్యాష్‌బోర్డ్‌కు తిరిగి', hi: '← डैशबोर्ड पर वापस' },

