  'vbook.askAddPerson': { en: '{name} is not in your family list yet. Shall I add them?', te: '{name} మీ కుటుంబ జాబితాలో ఇంకా లేరు. చేర్చమంటారా?', hi: '{name} अभी आपकी परिवार सूची में नहीं हैं। क्या मैं जोड़ दूँ?' },
  'vbook.askPersonName': { en: 'What is their name?', te: 'వారి పేరు ఏమిటి?', hi: 'उनका नाम क्या है?' },
  'vbook.askRelationName': { en: "What is {who}'s name?", te: '{who} పేరు ఏమిటి?', hi: '{who} का नाम क्या है?' },
