  'vbook.backHint': { en: 'You can also say "back" to change your last answer.', te: 'మీ చివరి సమాధానం మార్చడానికి "వెనక్కి" అని చెప్పవచ్చు.', hi: 'पिछला उत्तर बदलने के लिए "पीछे" कह सकते हैं।' },
  'vbook.didntCatch': { en: "Sorry, I didn't catch that. Please try again.", te: 'క్షమించండి, నాకు అర్థం కాలేదు. దయచేసి మళ్లీ ప్రయత్నించండి.', hi: 'माफ़ कीजिए, समझ नहीं आया। कृपया फिर कोशिश करें।' },
  'vbook.voiceOnDevice': { en: 'Using on-device voice', te: 'పరికరంలోని వాయిస్ వాడుతోంది', hi: 'डिवाइस की आवाज़ का उपयोग' },
  'vbook.voiceHigh': { en: 'High-accuracy voice on', te: 'అధిక-ఖచ్చితత్వ వాయిస్ ఆన్', hi: 'उच्च-सटीक आवाज़ चालू' },
